mapper.select:
SELECT
	 COUNT(SCRAB_RECUITMENT_DATE)
FROM SCRAB_RECRUITMENT
WHERE USER_ID = #{userId}
AND RECRUITMENT_NO = #{recruitmentNo}

mapper.insert:
INSERT INTO SCRAB_RECRUITMENT (
	USER_ID
	, RECRUITMENT_NO
	, SCRAB_RECUITMENT_DATE
) VALUES (
	#{userId}
	, #{recruitmentNo}
	, SYSDATE
)

mapper.delete:
DELETE FROM SCRAB_RECRUITMENT
WHERE USER_ID = #{userId}
AND RECRUITMENT_NO = #{recruitmentNo}
